import json, pathlib, re, collections
ROOT = pathlib.Path.home()/".claude"/"projects"
WRITE={"mcp__slack__chat_post_message","mcp__slack__chat_update","mcp__slack__chat_schedule_message"}
pat=re.compile(r'--body-file[= ]+([^\s;|&]+)')
firstchar=collections.Counter(); tilde=[]; n=0
for path in ROOT.rglob("*.jsonl"):
    try: raw=path.read_text(errors="replace").splitlines()
    except Exception: continue
    if not any('"mcp__slack__chat_' in l or "slack write" in l for l in raw): continue
    for line in raw:
        try: rec=json.loads(line)
        except Exception: continue
        if rec.get("type")!="assistant": continue
        for b in (rec.get("message") or {}).get("content") or []:
            if not isinstance(b,dict) or b.get("type")!="tool_use": continue
            inp=b.get("input") or {}
            cmd=inp.get("command") or ""
            if b.get("name")=="Bash" and "slack write" in cmd:
                n+=1
                for m in pat.finditer(cmd):
                    a=m.group(1); firstchar[a[:1]]+=1
                    if a.startswith("~") or a.startswith("'~") or a.startswith('"~'): tilde.append(a)
print("bash slack-write rows:", n)
print("body-file arg first chars:", dict(firstchar))
print("tilde-prefixed body-file args:", tilde)
EOF

