        .collect::<eyre::Result<Vec<String>>>()
    {
        Ok(bodies) => bodies,
        Err(e) => return SlackMcpServer::map_query_err(e),
    };

    // The SAME core `slack write --at` runs: chunk the parent, schedule the head, then route the
