/// Relay a follow-up that failed AFTER the parent went live, as a recoverable tool error.
///
/// Same contract as a `PartialPost` and a partial fan-out: the parent is already in the channel,
/// so the message says loudly which reply is missing and that the recovery is to thread the
/// REMAINING follow-ups - an LLM that reads "post failed" re-posts the whole thing and duplicates
/// a live message.
fn follow_up_failure(
    posted: &write::Posted,
    report: &write_follow_ups::FollowUpReport,
    landed: &[FollowUpPosted],
) -> Result<CallToolResult, McpError> {
    let (index, reason) = report
        .failure
        .as_ref()
        .expect("follow_up_failure is only called on a report carrying a failure");
    let total = report.requested();
    warn!(
        "post_message: follow-up {index}/{total} failed after the parent went live at {}",
        posted.permalink
    );
    let result = MessageResult {
        channel: posted.channel.clone(),
        ts: posted.ts.clone(),
        permalink: Some(posted.permalink.clone()),
        follow_ups: landed.to_vec(),
    };
    Ok(CallToolResult::error(vec![
        ContentBlock::text(format!(
            "the message POSTED and is live at {}, but follow-up {index} of {total} failed: \\
             {reason}. Do NOT re-post the message or the follow-ups that already landed - post \\
             only the remaining follow-ups as replies with thread_ts={}.",
            posted.permalink, posted.ts
        )),
        ContentBlock::json(&result)?,
    ]))
}"""
